export async function countIssues(
  orgId: OrgId,
  projectId: ProjectId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const sequence = getDb()
    .select({ value: issueNumberSequences.lastNumber })
    .from(issueNumberSequences)
    .where(
      and(
        orgPredicate(issueNumberSequences.orgId, orgId),
        eq(issueNumberSequences.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, sequence?.value ?? 0) + 1;
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db.transaction((tx) => {
    const inserted = tx
      .insert(issues)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        number: issueNumber,
        title: input.title,
        description: input.description,
        status: input.status,
        priority: input.priority,
        authorId,
        assigneeId: input.assigneeId,
        parentId: input.parentId,
        estimate: input.estimate,
        dueAt: input.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    if (input.labelIds.length > 0) {
      tx.insert(issueLabels)
        .values(
          input.labelIds.map((labelId) => ({
            orgId: input.orgId,
            issueId: inserted.id,
            labelId,
          })),
        )
        .run();
    }

    tx.insert(issueNumberSequences)
      .values({
        orgId: input.orgId,
        projectId: input.projectId,
        lastNumber: issueNumber,
      })
      .onConflictDoUpdate({
        target: [issueNumberSequences.orgId, issueNumberSequences.projectId],
        set: {
